patch:
diff --git a/repro-19818.js b/repro-19818.js
new file mode 100644
index 0000000..bb183c2
--- /dev/null
+++ b/repro-19818.js
@@ -0,0 +1,61 @@
+/* eslint no-console: "off" -- repro script output */
+"use strict";
+
+/*
+ * Reproduction for eslint/eslint#19818:
+ * `no-useless-assignment` reports the operand of a prefix `++`/`--` whose
+ * result is consumed by the enclosing expression (returned / passed on).
+ * Run: node repro-19818.js   (exits 1 when the bug reproduces)
+ */
+
+const { Linter } = require("./lib/api");
+
+const linter = new Linter();
+const config = { rules: { "no-useless-assignment": "error" } };
+
+const cases = [
+	// [code, expectedErrors, note]
+	["[1, 2, 3].map(i => ++i);", 0, "report: arrow returns ++i"],
+	["[1, 2, 3].map(i => --i);", 0, "report: arrow returns --i"],
+	["[1, 2, 3].map(i => i + 1);", 0, "report control"],
+	["[1, 2, 3].map(i => i - 1);", 0, "report control"],
+	["function f(i) { return ++i; }", 0, "return of prefix update"],
+	["function f(i) { foo(++i); }", 0, "prefix update as call argument"],
+	["function f(i) { const j = ++i; return j; }", 0, "prefix update as initializer"],
+	// Related, informational (expected = null): plain/compound assignments whose value is consumed.
+	["function f(i) { return i = i + 1; }", null, "related: assignment used as value"],
+	["function f(i) { return i += 1; }", null, "related: compound assignment used as value"],
+	["[1, 2, 3].map(i => i += 1);", null, "related: arrow returns i += 1"],
+	["function f(i) { ++i; }", 1, "true positive: result discarded"],
+	["function f(i) { return i++; }", 1, "postfix: new value really unused"],
+];
+
+let failures = 0;
+
+/**
+ * Formats the status column.
+ * @param {boolean} ok Whether the case matched its expectation.
+ * @returns {string} The status label.
+ */
+function getStatus(ok) {
+	return ok ? "ok  " : "FAIL";
+}
+
+for (const [code, expected, note] of cases) {
+	const messages = linter.verify(code, config);
+	const actual = messages.length;
+	const ok = expected === null || actual === expected;
+
+	if (!ok) {
+		failures++;
+	}
+	console.log(
+		`${expected === null ? "info" : getStatus(ok)} expected ${expected ?? "-"}, got ${actual}  ${code}  // ${note}`,
+	);
+	for (const m of messages) {
+		console.log(`       ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+	}
+}
+
+console.log(failures ? `\n${failures} case(s) diverge from expected: bug reproduced.` : "\nAll cases as expected.");
+process.exitCode = failures ? 1 : 0;
